import time
from dataclasses import dataclass

@dataclass
class Mem:
    text: str
    kind: str
    importance: float
    created_at: float
    ttl: float | None = None
    active: bool = True

def admit(cand, existing, sim, min_imp=0.55, dup=0.92):
    if cand.importance < min_imp:
        return None
    if cand.kind == 'episode' and cand.importance < 0.7:
        return None
    for e in existing:
        if e.active and sim(cand.text, e.text) > dup:
            return None
    return cand

def recall(qvec, items, embed, cosine, now=None, k=5):
    now = now or time.time()
    out = []
    for m in items:
        if not m.active:
            continue
        if m.ttl and now - m.created_at > m.ttl:
            continue
        rel = cosine(qvec, embed(m.text))
        if rel < 0.35:
            continue
        rec = 0.5 ** ((now - m.created_at) / 86400 / 30)
        score = 0.62 * rel + 0.23 * m.importance + 0.15 * rec
        out.append((score, m))
    out.sort(key=lambda x: -x[0])
    return [m for _, m in out[:k]]

from hashlib import sha256

def render_tools(tools):
    return '\n'.join(f"{t['name']}: {t['description']}" for t in tools)

def build_prompt(system_static, tool_schemas, history, user_input):
    tools = sorted(tool_schemas, key=lambda t: t['name'])
    msgs = [
        {'role': 'system', 'content': system_static},
        {'role': 'system', 'content': render_tools(tools)},
    ]
    msgs.extend(history)
    msgs.append({'role': 'user', 'content': user_input})
    return msgs

def compact_tool_result(text, store, limit=8000):
    if len(text) <= limit:
        return text
    key = sha256(text.encode()).hexdigest()[:16]
    store.put(key, text)
    head = text[:limit]
    return f'ref={key} total={len(text)}\n{head}'

def log_prefix_hash(msgs):
    blob = ''.join(m['content'] for m in msgs)
    return sha256(blob.encode()).hexdigest()[:12]

REGISTRY = {
    "researcher": {"tags": ["search"], "cost": 2, "p95_ms": 4000, "fanout_ok": True},
    "coder":      {"tags": ["code"],   "cost": 3, "p95_ms": 9000, "fanout_ok": False},
