        return {"answer": best_partial(steps), "partial": True, "missing": what_missing(steps)}
    return {"answer": compose(steps), "partial": False}

async def retrieve(q: str, kb: str):
    base = await vector_search(q, kb, top_k=20)
    if not need_hyde(q, base):
        return fuse(base)
    try:
        hypo = await llm.agenerate(HYDE_PROMPT.format(q=q), max_tokens=160, timeout=0.6)
    except (asyncio.TimeoutError, LLMError):
        return fuse(base)
    hypo_hits = await vector_search(hypo, kb, top_k=20)
    return fuse(base, hypo_hits, weights=(0.4, 0.6))

def need_hyde(q: str, base) -> bool:
    if has_rare_entity(q):        # 错误码、型号、数字
        return False
    if len(tokenize(q)) > 12:
        return False
    return not base or base[0].score < SCORE_GATE

def dedup_by_parent(chunks):
    seen, out = set(), []
    for c in sorted(chunks, key=lambda x: -x['score']):
        key = (c['doc_id'], c['parent_id'])
        if key in seen:
            continue
        seen.add(key)
        out.append(c)
    return out

def arrange(chunks, k=6, mode='sandwich'):
    picked = dedup_by_parent(chunks)[:k]
    if mode == 'sim':
        return picked
    half = max(1, len(picked) // 2)
    front, back = picked[:half], picked[half:]
    return front + list(reversed(back))

def position_sensitivity(run_qa, queries, pool, modes=('sim', 'reverse', 'sandwich')):
    report = {}
    for mode in modes:
        hits = []
        for q in queries:
            ctx = arrange(pool[q['id']], mode=mode)
            ans = run_qa(q['text'], ctx)
            hits.append(1.0 if q['gold_id'] in ans.citations else 0.0)
        report[mode] = round(sum(hits) / len(hits), 4)
    return report

import numpy as np

def truncate(vec, dim):
    v = np.asarray(vec, dtype='float32')[:dim]
    n = np.linalg.norm(v)
    return v / n if n else v

def slice_recall(queries, gold, k=10, dims=(1536, 512, 256)):
    out = {}
    for d in dims:
        per_slice = {}
        for q in queries:
            qv = truncate(q['emb'], d)
            scored = sorted(
                ((float(truncate(c['emb'], d) @ qv), c['id']) for c in q['cands']),
                reverse=True,
            )
            hit = 1.0 if gold[q['id']] in [i for _, i in scored[:k]] else 0.0
            per_slice.setdefault(q['slice'], []).append(hit)
        out[d] = {s: round(sum(v) / len(v), 4) for s, v in per_slice.items()}
    return out

import json
from pydantic import BaseModel, ConfigDict
from pydantic.alias_generators import to_camel

class WireModel(BaseModel):
    model_config = ConfigDict(alias_generator=to_camel, populate_by_name=True)

class ChatRequest(WireModel):
    request_id: str
    user_query: str

class CachePayload(WireModel):
    request_id: str
    user_query: str

def dump_wire(m: BaseModel) -> dict:
    return m.model_dump(by_alias=True, mode="json", exclude_none=True)

def load_wire(data: dict) -> ChatRequest:
    return ChatRequest.model_validate(data)

@app.post("/chat", response_model=ChatRequest, response_model_by_alias=True)
async def chat(req: ChatRequest):
    payload = CachePayload(request_id=req.request_id, user_query=req.user_query)
    await redis.set(req.request_id, json.dumps(dump_wire(payload)))
    return req

from fastapi import FastAPI, UploadFile, HTTPException
import httpx

CHUNK = 1024 * 1024
MAX_BYTES = 200 * 1024 * 1024

class TooLarge(Exception):
    pass

@app.post("/v1/files")
async def upload(file: UploadFile):
    total = 0
    try:
        async with httpx.AsyncClient(timeout=httpx.Timeout(60.0, read=300.0)) as client:
            async def body_iter():
                nonlocal total
                while chunk := await file.read(CHUNK):
                    total += len(chunk)
                    if total > MAX_BYTES:
                        raise TooLarge
                    yield chunk
            try:
                resp = await client.post(
                    "http://model-gateway/v1/files",
                    content=body_iter(),
                    headers={"content-type": file.content_type or "application/octet-stream"},
                )
            except TooLarge:
                raise HTTPException(status_code=413, detail="file too large")
        if resp.status_code >= 400:
            raise HTTPException(status_code=502, detail="gateway error")
        return {"bytes": total}
    finally:
        await file.close()
